ted=`<h2>Deleted items</h2>${gone.length?`<div class="sheet-w"><table class="sheet"><thead><tr><th>Name</th><th>Category</th><th class="r">Price (₱)</th><th></th></tr></thead><tbody>${gone.map(g=>`<tr><td>${esc(g.n)}</td><td>${esc(g.c)}</td><td class="r">${g.p}</td><td class="ac"><button class="btn s" onclick="restore('${g.id}')">Restore</button></td></tr>`).join("")}</tbody></table></div>`:"<p>Nothing deleted.</p>"}`;P.locations=`<h2>Locations</h2><div class="sheet-w"><table class="sheet"><thead><tr><th>Branch</th><th>Address</th><th>Phone</th><th>Opens</th><th>Closes</th><th>Status</th><th></th></tr></thead><tbody>${BR.filter(b=>!SCB||b.id===SCB).map(b=>`<tr><td class="in"><input aria-label="Branch name" value="${esc(b.n)}" onchange="edb('${b.id}','n',this.value)"></td><td class="in w2"><input aria-label="Address" value="${esc(b.a)}" onchange="edb('${b.id}','a',this.value)"></td><td class="in"><input aria-label="Phone" value="${esc(b.ph)}" onchange="edb('${b.id}','ph',this.value)"></td><td class="in"><select aria-label="Opens" onchange="edb('${b.id}','o',this.value)">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===b.o?"selected":""}>${hrs(h)}</option>`).join("")}</select></td><td class="in"><select aria-label="Closes" onchange="edb('${b.id}','c',this.value)">${Array.from({length:24},(_,h)=>h+1).map(h=>`<option value="${h}" ${h===b.c?"selected":""}>${hrs(h)}</option>`).join("")}</select></td><td>${b.paused?"Paused":brOpen(b)?"Open":"Closed"}</td><td class="ac"><button class="btn s" onclick="tgb('${b.id}')">${b.paused?"Resume orders":"Pause orders"}</button></td></tr>`).join("")}</tbody></table></div><p class="hint">Paused branches don’t appear at checkout.</p>`;
 P.promos=`<h2>Promotions</h2><div class="sheet-w"><table class="sheet"><thead><tr><th>Promo</th><th>Rule</th><th>Value</th><th>Status</th><th></th></tr></thead><tbody>${[["tue","STACK’D Tuesday","Percent off selected burgers on Tuesdays (choose burgers under Menu)","pct","%"],["dt","Double Trouble","Bundle price for two Classic Stacks (regular "+PHP(cp()*2)+")","price","₱"],["stu","Student Stack","Percent off with a valid student ID","pct","%"]].map(x=>`<tr><td>${x[1]}</td><td class="wrap">${x[2]}</td><td class="in"><input class="r" type="number" min="1" ${x[3]==="pct"?'max="100"':""} aria-label="${x[1]} value" value="${PR(x[0])[x[3]]}" onchange="edp('${x[0]}','${x[3]}',this.value)"></td><td>${PR(x[0]).on?"On":"Off"} <span class="mut">${x[4]}</span></td><td class="ac"><button class="btn s" onclick="tgp('${x[0]}')">${PR(x[0]).on?"Turn off":"Turn on"}</button></td></tr>`).join("")}</tbody></table></div><p class="hint">Order of application: Double Trouble, then Tuesday on the rest, then Student Stack.</p>`;
 P.settings=`<h2>Settings</h2><div class="ad-bar"><label for="fee" style="margin:0">Delivery fee (PHP)</label><input id="fee" type="number" min="0" value="${FEE}" style="max-width:120px" onchange="setFee(this.value)"><button class="btn s" onclick="resetMenu()">Reset menu changes</button><button class="btn s" onclick="resetStore()">Reset locations and promos</button><button class="btn s" onclick="loadDemo()">Load demo data</button><button class="btn s" onclick="clearOrders()">Clear all orders</button><button class="btn s" onclick="logout()">Sign out</button></div>`;
