const adminsLeft=(skip)=>S.users.filter(u=>u.role==="admin"&&u.on&&u.id!==skip).length;
function setRole(id,r){const u=S.users.find(x=>x.id===id);if(!u||!ROLES[r]||me().id===id)return route();if(u.role==="admin"&&r!=="admin"&&!adminsLeft(id)){route();return toast("Keep at least one active admin")}u.role=r;if(["staff","manager"].includes(r)&&!u.br)u.br=BR[0].id;if(["admin","customer"].includes(r))u.br=null;save();route();toast("Role updated")}
function setUBr(id,b){const u=S.users.find(x=>x.id===id);if(!u||!BR.some(x=>x.id===b))return;u.br=b;save();route();toast("Branch updated")}
function toggleUser(id){const u=S.users.find(x=>x.id===id);if(!u||me().id===id)return;if(u.on&&u.role==="admin"&&!adminsLeft(id))return toast("Keep at least one active admin");u.on=u.on?0:1;save();route()}
function resetPw(id){const u=S.users.find(x=>x.id===id);if(!u)return;ask({title:"Reset password?",msg:"Sets the password for "+u.name+" to the demo password ("+DEMO_PW+").",ok:"Reset"},()=>{u.sl=Math.random().toString(36).slice(2,8);u.h=hashPw(DEMO_PW,u.sl);save();toast("Password reset")})}
function delUser(id){const u=S.users.find(x=>x.id===id);if(!u||me().id===id)return;if(u.role==="admin"&&u.on&&!adminsLeft(id))return toast("Keep at least one active admin");ask({title:"Delete this account?",msg:u.name+" ("+u.email+") will be deleted. Their past orders stay in the system.",ok:"Delete",danger:1},()=>{S.users=S.users.filter(x=>x.id!==id);save();route()})}
function addUser(){const n=$("#un").value.trim(),em=$("#ue").value.trim().toLowerCase(),r=$("#ur").value,pw=$("#up").value;if(!n)return toast("Enter a name");if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em))return toast("Enter a valid email");if(S.users.some(u=>u.email===em))return toast("That email is already used");if(pw.length<8)return toast("Password needs 8+ characters");
 const u=mkU("u_"+Date.now().toString(36),n,em,r,["staff","manager"].includes(r)?$("#ub").value:null,"");u.h=hashPw(pw,u.sl);S.users.push(u);save();route();toast("Account added")}

