 const top=[...act].sort((a,b)=>b.sp-a.sp).slice(0,10),fav=h=>Object.entries(h.it).sort((a,b)=>b[1]-a[1])[0],hb=h=>{const e=Object.entries(h.br).sort((a,b)=>b[1]-a[1])[0];return e?brn(e[0]).replace(" – Main Branch","").replace(" Branch",""):"—"};
