const MK='<svg class="mk" viewBox="0 0 32 32" aria-hidden="true"><rect x="4" y="3" width="24" height="9" rx="4.5" fill="#F2BD45"/><rect x="2" y="14" width="28" height="4" rx="2" fill="#F5EBD8"/><rect x="4" y="20" width="24" height="9" rx="4.5" fill="#F2BD45"/></svg>';
const CK='<svg class="ck" aria-hidden="true"><defs><pattern id="ckp" width="16" height="16" patternUnits="userSpaceOnUse"><rect width="8" height="8" fill="#F5EBD8"/><rect x="8" y="8" width="8" height="8" fill="#F5EBD8"/></pattern></defs><rect width="100%" height="16" fill="#191919"/><rect width="100%" height="16" fill="url(#ckp)"/></svg>';
function mark(){let h=hh().slice(1);if(h==="promos"||h.startsWith("item-"))h="menu";document.querySelectorAll("header nav a").forEach(a=>{if(a.getAttribute("href")==="#"+h)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")})}
function closeNav(){const nv=$("#nv");if(nv&&nv.classList.contains("open")){nv.classList.remove("open");$("#mb").setAttribute("aria-expanded","false");$("#mb").innerHTML=ic("menu")}}
document.addEventListener("click",e=>{if(!e.composedPath().some(n=>n.id==="mb"||n.id==="nv"))closeNav()});addEventListener("keydown",e=>{if(e.key==="Escape")closeNav()});
const isDark=()=>{const t=document.documentElement.getAttribute("data-theme");return t?t==="dark":matchMedia("(prefers-color-scheme:dark)").matches};
const themeBtn=()=>`<button type="button" class="th" id="thb" onclick="toggleTheme()" aria-label="${isDark()?"Switch to light theme":"Switch to dark theme"}" title="${isDark()?"Light theme":"Dark theme"}">${ic(isDark()?"weather-sunny":"weather-night")}</button>`;
function toggleTheme(){const t=isDark()?"light":"dark";document.documentElement.setAttribute("data-theme",t);try{localStorage.setItem("stackd-theme",t)}catch(e){}const b=$("#thb");if(b)b.outerHTML=themeBtn();const f=$("#thb");if(f)f.focus()}
function chrome(){
 $("#hd").innerHTML=`<a class="logo" href="#home" aria-label="STACK’D home">${MK}STACK’D</a><nav id="nv" aria-label="Main">${[["home","Home"],["menu","Menu and deals"],["locations","Locations"],["about","Our story"],...navExtra()].map(l=>`<a href="#${l[0]}">${l[1]}</a>`).join("")}</nav><div class="hr"><a class="btn s" href="#menu">Order Now</a>${themeBtn()}<a class="cartl" id="cartbtn" href="#order" aria-label="Cart">${ic("cart-outline")}<b id="cc">0</b></a><button class="mb" id="mb" aria-label="Menu" aria-expanded="false" aria-controls="nv">${ic("menu")}</button></div>`;
 $("#mb").onclick=()=>{const o=$("#nv").classList.toggle("open");$("#mb").setAttribute("aria-expanded",o);$("#mb").innerHTML=ic(o?"close":"menu")};
 $("#ft").innerHTML=`${CK}<div class="fw"><div><div class="fbrand">${MK}STACK’D</div><p>Big stacks. Bigger cravings.</p><a class="btn s" href="#menu">Order Now</a></div>
 <div><h4>Explore</h4><ul>${[["menu","Menu and deals"],["locations","Locations"],["about","Our story"],["contact","Contact"],["legal","Privacy and terms"]].map(l=>`<li><a href="#${l[0]}">${l[1]}</a></li>`).join("")}</ul></div>
 <div><h4>Visit and call</h4><ul><li class="fl">${ic("clock-outline")}${hrsAll()?"Every day, "+hrsAll():"Hours vary by branch"}</li><li class="fl">${ic("phone")}+63 900 000 0000 (placeholder)</li><li class="fl">${ic("email-outline")}hello@stackdburgers.example</li><li class="fl">${ic("map-marker")}4 branches across Laguna</li></ul></div>
 <div><h4>Branches</h4><ul>${BR.map(b=>`<li><a href="#locations">${b.n}</a></li>`).join("")}</ul></div></div>
 <div class="fcon" id="contact"><div><h4>Contact us</h4><p>Questions or feedback? Drop us a line.</p></div><form id="cf" onsubmit="return fsend(event)" novalidate><div class="fcr"><div><label for="cn">Name</label><input id="cn" placeholder="Name" autocomplete="name" required></div><div><label for="ce">Email</label><input id="ce" type="email" placeholder="Email" autocomplete="email" required></div></div><label for="cm">Message</label><textarea id="cm" rows="1" placeholder="Message" required></textarea><p><button class="btn" type="submit">Send message</button></p></form></div>
 <div class="fb"><span>© 2026 STACK’D Burgers</span><span><strong>Showcase only.</strong> No real orders or payments. Branch names, addresses and contact details are placeholders.</span></div>`}
const D_BURGER=`<svg class="deco" viewBox="0 0 100 80" aria-hidden="true"><defs><mask id="bite"><rect width="100" height="80" fill="#fff"/><circle cx="94" cy="16" r="11"/><circle cx="99" cy="36" r="10"/><circle cx="90" cy="3" r="9"/></mask></defs><g mask="url(#bite)"><path d="M10 36C10 12 30 6 50 6s40 6 40 30z" fill="currentColor"/><g fill="#F2BD45"><ellipse cx="32" cy="20" rx="3.2" ry="1.7" transform="rotate(-20 32 20)"/><ellipse cx="50" cy="14" rx="3.2" ry="1.7"/><ellipse cx="66" cy="22" rx="3.2" ry="1.7" transform="rotate(20 66 22)"/><ellipse cx="46" cy="27" rx="3.2" ry="1.7" transform="rotate(-10 46 27)"/></g><path d="M6 38h88l-12 11-10-9-14 12-10-12H6z" fill="#F5EBD8" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><rect x="8" y="46" width="84" height="12" rx="6" fill="currentColor"/><path d="M10 62h80c0 9-8 14-20 14H30c-12 0-20-5-20-14z" fill="currentColor"/></g></svg>`,D_CHEESE=`<svg class="deco" viewBox="0 0 100 80" aria-hidden="true"><path d="M4 38 64 8q6-3 12 1l20 14v28L36 76 4 62z" fill="currentColor"/><path d="M4 38 64 8l32 15-60 28z" fill="#F5EBD8" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><g fill="#F2BD45"><circle cx="58" cy="24" r="3.5"/><circle cx="40" cy="33" r="2.5"/><circle cx="18" cy="52" r="4"/><circle cx="26" cy="64" r="2.5"/><circle cx="62" cy="52" r="5"/><circle cx="80" cy="42" r="3"/><circle cx="50" cy="66" r="2.6"/></g></svg>`;
function promoStrip(){const L=[];
 if(PR("tue").on)L.push(`<div class="promo"><h3>${ic("calendar-star")}STACK’D Tuesday</h3>${tueTxt()}${isTue()?"<strong>Live today.</strong>":"Applied automatically in your cart."}${D_CHEESE}</div>`);
 if(PR("dt").on)L.push(`<div class="promo"><h3>${ic("sale")}Double Trouble</h3>${dtTxt()}<p style="margin:8px 0 0"><button class="btn s" onclick="add('classic');add('classic')">Add the deal</button></p>${D_BURGER}</div>`);
 if(PR("stu").on)L.push(`<div class="promo"><h3>${ic("school")}Student Stack</h3>${stuTxt()} Tick the box at checkout.${D_CHEESE}</div>`);
 if(!L.length)return `<section id="promos" aria-label="Deals"><p>No deals running right now. Check back soon.</p></section>`;
 return `<section id="promos" aria-label="Deals"><div class="pgrid" tabindex="0" role="group" aria-label="Current deals">${L.join("")}</div><div class="pnav"><button type="button" class="pb" data-pc="-1" aria-label="Previous deal">‹</button><span class="pdots" aria-hidden="true">${L.map((_,k)=>`<i${k?"":' class="on"'}></i>`).join("")}</span><button type="button" class="pb" data-pc="1" aria-label="Next deal">›</button></div><small class="dnote">${ic("sale")}<span>Deals apply in this order: Double Trouble, Tuesday on the rest, then Student Stack.</span>${D_BURGER}</small></section>`}
